    var dt=new Date(d.generatedAt);
    var stamp=isNaN(dt.getTime())?'':(' · 更新于 '+(dt.getMonth()+1)+' 月 '+dt.getDate()+' 日');
    document.getElementById('meta').textContent=total+' 个文件 · '+data.courses.length+' 门课'+stamp;
